// XHR 拦截器 - 拦截嵌入式地图数据请求
(function() {
    var _origOpen = XMLHttpRequest.prototype.open;
    var _origSend = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.open = function(method, url) {
        this._url = url;
        this._async = arguments[2] !== false;
        // 不调用原始 open，避免 file:// URL 导致 CORS 错误
        // 用 about:blank 初始化 xhr 状态，使 overrideMimeType 等方法可用
        return _origOpen.call(this, 'GET', 'about:blank', true);
    };
    XMLHttpRequest.prototype.send = function() {
        var xhr = this;
        var url = xhr._url || '';
        var embeddedData = null;
        
        // 拦截地图数据请求
        var mapMatch = url.match(/Map(\d+)\.json$/);
        if (mapMatch && window.USE_EMBEDDED_DATA) {
            var id = parseInt(mapMatch[1]);
            if (window.$dataMaps && window.$dataMaps[id]) {
                embeddedData = window.$dataMaps[id];
            }
        }
        
        if (embeddedData) {
            var jsonStr = JSON.stringify(embeddedData);
            Object.defineProperty(xhr, 'responseText', { get: function() { return jsonStr; } });
            Object.defineProperty(xhr, 'response', { get: function() { return embeddedData; } });
            Object.defineProperty(xhr, 'status', { get: function() { return 200; } });
            Object.defineProperty(xhr, 'readyState', { get: function() { return 4; } });
            Object.defineProperty(xhr, 'statusText', { get: function() { return 'OK'; } });
            // 同步调用 onload（onload 在 send() 之前已设置）
            if (xhr.onload) xhr.onload();
            if (xhr.onreadystatechange) xhr.onreadystatechange();
            return;
        }
        
        // 非嵌入式数据请求 - 恢复原始 open 并重新发送
        _origOpen.apply(xhr, ['GET', url, xhr._async]);
        return _origSend.apply(this, arguments);
    };
})();

